import{_ as t,o as i,c as l,ae as o}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"Pixiu 明細インポート","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/guide/07-pixiu-bill-import-guide.md","filePath":"v1/ja/guide/07-pixiu-bill-import-guide.md"}'),r={name:"v1/ja/guide/07-pixiu-bill-import-guide.md"};function e(d,a,n,h,s,u){return i(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="pixiu-明細インポート" tabindex="-1">Pixiu 明細インポート <a class="header-anchor" href="#pixiu-明細インポート" aria-label="Permalink to &quot;Pixiu 明細インポート&quot;">​</a></h1><h2 id="📋-概要" tabindex="-1">📋 概要 <a class="header-anchor" href="#📋-概要" aria-label="Permalink to &quot;📋 概要&quot;">​</a></h2><p>本ガイドでは、<strong>Pixiu</strong> から書き出した明細（CSV）を <strong>Koala</strong> にインポートする手順を説明します。</p><p>Koala は現在、<strong>Pixiu の CSV エクスポート</strong>（CSV のみ）に対応しています。</p><hr><h2 id="📱-手順-1-pixiu-で明細をエクスポート" tabindex="-1">📱 手順 1：Pixiu で明細をエクスポート <a class="header-anchor" href="#📱-手順-1-pixiu-で明細をエクスポート" aria-label="Permalink to &quot;📱 手順 1：Pixiu で明細をエクスポート&quot;">​</a></h2><p>Pixiu はバージョンによってメニュー名が多少異なりますが、流れは共通です。「データ書き出し/明細書き出し」から期間を選び、CSV で保存します。</p><h3 id="手順-1-エクスポート画面を開く" tabindex="-1">手順 1：エクスポート画面を開く <a class="header-anchor" href="#手順-1-エクスポート画面を開く" aria-label="Permalink to &quot;手順 1：エクスポート画面を開く&quot;">​</a></h3><ol><li>Pixiu を開く</li><li><strong>「我的」</strong> を開く</li><li><strong>「数据导出」/「导出账单」</strong>（表記は異なる場合あり）を探す</li></ol><h3 id="手順-2-期間を選択" tabindex="-1">手順 2：期間を選択 <a class="header-anchor" href="#手順-2-期間を選択" aria-label="Permalink to &quot;手順 2：期間を選択&quot;">​</a></h3><ol><li>期間（例：直近 1 か月 / 直近 3 か月など）を選ぶ</li><li>確定してエクスポートを開始</li></ol><blockquote><p>💡 ヒント：</p><ul><li>1 回のエクスポートは 3 か月以内をおすすめします（ファイルが大きいと解析が遅くなることがあります）。</li><li>データ量が多い場合は複数回に分けてエクスポートし、分割してインポートしてください。</li></ul></blockquote><h3 id="手順-3-csv-で保存" tabindex="-1">手順 3：CSV で保存 <a class="header-anchor" href="#手順-3-csv-で保存" aria-label="Permalink to &quot;手順 3：CSV で保存&quot;">​</a></h3><ol><li>形式は <strong>CSV</strong> を選択</li><li>端末内に保存（共有 → ファイルに保存 など）</li><li>保存先を覚えておく</li></ol><hr><h2 id="📱-手順-2-koala-にインポート" tabindex="-1">📱 手順 2：Koala にインポート <a class="header-anchor" href="#📱-手順-2-koala-にインポート" aria-label="Permalink to &quot;📱 手順 2：Koala にインポート&quot;">​</a></h2><h3 id="手順-1-インポート画面を開く" tabindex="-1">手順 1：インポート画面を開く <a class="header-anchor" href="#手順-1-インポート画面を開く" aria-label="Permalink to &quot;手順 1：インポート画面を開く&quot;">​</a></h3><ol><li>Koala を開く</li><li><strong>「設定」</strong> → <strong>「明細インポート」</strong></li></ol><h3 id="手順-2-インポート元を選択" tabindex="-1">手順 2：インポート元を選択 <a class="header-anchor" href="#手順-2-インポート元を選択" aria-label="Permalink to &quot;手順 2：インポート元を選択&quot;">​</a></h3><ol><li><strong>「インポート元」</strong> をタップ</li><li><strong>「Pixiu」</strong> を選択</li></ol><blockquote><p>⚠️ 重要：必ず Pixiu を選択してください。選択を間違えると検証に失敗したり、列の読み取りがずれることがあります。</p></blockquote><h3 id="手順-3-ファイルを選択" tabindex="-1">手順 3：ファイルを選択 <a class="header-anchor" href="#手順-3-ファイルを選択" aria-label="Permalink to &quot;手順 3：ファイルを選択&quot;">​</a></h3><ol><li><strong>「ファイルパス」</strong> をタップ</li><li>Pixiu から書き出した <strong>CSV</strong> を選択</li><li>ファイル名が表示されることを確認</li></ol><h3 id="手順-4-帳本-ledger-を関連付け" tabindex="-1">手順 4：帳本（Ledger）を関連付け <a class="header-anchor" href="#手順-4-帳本-ledger-を関連付け" aria-label="Permalink to &quot;手順 4：帳本（Ledger）を関連付け&quot;">​</a></h3><ol><li><strong>「関連付け帳本」</strong> をタップ</li><li>取り込み先の帳本を選択</li></ol><h3 id="手順-5-解析-→-プレビュー" tabindex="-1">手順 5：解析 → プレビュー <a class="header-anchor" href="#手順-5-解析-→-プレビュー" aria-label="Permalink to &quot;手順 5：解析 → プレビュー&quot;">​</a></h3><ol><li>右上の <strong>「解析」</strong> をタップ</li><li>成功するとプレビュー画面へ移動</li><li>1 件ずつ編集/削除、または無効な明細をまとめてスキップできます</li></ol><h3 id="手順-6-インポート実行" tabindex="-1">手順 6：インポート実行 <a class="header-anchor" href="#手順-6-インポート実行" aria-label="Permalink to &quot;手順 6：インポート実行&quot;">​</a></h3><ol><li>内容を確認したら <strong>「インポート」</strong> をタップ</li><li>完了まで待つ</li></ol><hr><h2 id="📋-pixiu-csv-の形式-参考" tabindex="-1">📋 Pixiu CSV の形式（参考） <a class="header-anchor" href="#📋-pixiu-csv-の形式-参考" aria-label="Permalink to &quot;📋 Pixiu CSV の形式（参考）&quot;">​</a></h2><p>Koala の検証ポイント：</p><ul><li>1 行目はヘッダー必須</li><li><strong>ヘッダー列数は 10 列</strong></li><li>区切りはカンマ <code>,</code>（標準 CSV）</li></ul><h3 id="列定義-順番" tabindex="-1">列定義（順番） <a class="header-anchor" href="#列定義-順番" aria-label="Permalink to &quot;列定義（順番）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>列</th><th>意味</th><th>説明</th></tr></thead><tbody><tr><td>1</td><td>日付</td><td><code>yyyy-MM-dd</code> / <code>yyyy/MM/dd</code> に対応。年は 2016 以上が必要（それ以外は無効）</td></tr><tr><td>2</td><td>親カテゴリ</td><td>Koala の親カテゴリ名と照合</td></tr><tr><td>3</td><td>取引種別</td><td>「支出」または「收入」を含む必要あり。「收入」を含む場合は収入として取り込み、それ以外は支出として取り込み</td></tr><tr><td>4</td><td>子カテゴリ</td><td>Koala の子カテゴリ名と照合</td></tr><tr><td>5</td><td>入金額</td><td>収入金額（<code>-</code> が付いていても可。取り込み時に符号は除去されます）</td></tr><tr><td>6</td><td>出金額</td><td>支出金額（<code>-</code> が付いていても可。取り込み時に符号は除去されます）</td></tr><tr><td>7</td><td>通貨コード</td><td><code>CNY</code> / <code>USD</code> など。空の場合は取り込み先帳本の通貨を使用</td></tr><tr><td>8</td><td>口座</td><td>口座名（名称で照合。存在しない場合は取り込み時に作成されることがあります）</td></tr><tr><td>9</td><td>タグ</td><td>複数タグはカンマ区切り（<code>,</code>）。中国語カンマ <code>，</code> も対応</td></tr><tr><td>10</td><td>メモ</td><td>メモ本文</td></tr></tbody></table><h3 id="koala-への取り込み-概要" tabindex="-1">Koala への取り込み（概要） <a class="header-anchor" href="#koala-への取り込み-概要" aria-label="Permalink to &quot;Koala への取り込み（概要）&quot;">​</a></h3><ul><li>日付 → 日付</li><li>取引種別 → 収入/支出</li><li>親 + 子カテゴリ → カテゴリ（未一致の場合は「不完全」としてプレビューで修正が必要）</li><li>入金/出金 → 金額（収入/支出で参照列が決まります）</li><li>口座 → 口座</li><li>タグ → タグ（名称で照合/作成して紐付け）</li><li>メモ → メモ</li><li>通貨コード → 通貨（一致しない場合は帳本通貨にフォールバック）</li></ul><hr><h2 id="⚠️-注意事項" tabindex="-1">⚠️ 注意事項 <a class="header-anchor" href="#⚠️-注意事項" aria-label="Permalink to &quot;⚠️ 注意事項&quot;">​</a></h2><ol><li><strong>自動重複排除なし</strong>：同じファイルを二重に取り込むと重複明細が作成されます。取り込み範囲の重複に注意してください。</li><li><strong>カテゴリ一致</strong>：親 + 子の名称で一致させます。未一致の場合はプレビューで修正してから取り込んでください。</li><li><strong>口座の有効性</strong>：口座名が空、または記号のみの場合は無効として扱われ、補完が必要になることがあります。</li><li><strong>文字化け</strong>：CSV は UTF-8/GBK に対応しています。文字化けする場合は UTF-8 で再書き出し、または文字コード変換してから取り込んでください。</li></ol><hr><h2 id="🔧-よくある質問" tabindex="-1">🔧 よくある質問 <a class="header-anchor" href="#🔧-よくある質問" aria-label="Permalink to &quot;🔧 よくある質問&quot;">​</a></h2><h3 id="q1-「ヘッダーの列数が不正」と表示されます" tabindex="-1">Q1：「ヘッダーの列数が不正」と表示されます <a class="header-anchor" href="#q1-「ヘッダーの列数が不正」と表示されます" aria-label="Permalink to &quot;Q1：「ヘッダーの列数が不正」と表示されます&quot;">​</a></h3><p>CSV の 1 行目が <strong>10 列</strong> になっているか確認してください。よくある原因：</p><ol><li>Pixiu 以外の CSV を使っている（列数が違う）</li><li>Excel/WPS で編集して区切りが増え、列数が変わった</li><li>互換性のない形式で保存した（例：セミコロン区切り）</li></ol><h3 id="q2-金額が-0-になる-おかしい" tabindex="-1">Q2：金額が 0 になる／おかしい <a class="header-anchor" href="#q2-金額が-0-になる-おかしい" aria-label="Permalink to &quot;Q2：金額が 0 になる／おかしい&quot;">​</a></h3><p>確認：</p><ol><li>「取引種別」列に「支出/收入」のキーワードが含まれているか（入金/出金のどちらを読むかが決まります）</li><li>対応する金額列が数値になっているか（<code>-</code> があっても可）</li></ol><h3 id="q3-カテゴリが一致しません" tabindex="-1">Q3：カテゴリが一致しません <a class="header-anchor" href="#q3-カテゴリが一致しません" aria-label="Permalink to &quot;Q3：カテゴリが一致しません&quot;">​</a></h3><p>プレビューで 1 件ずつ正しいカテゴリを選択してください。もしくは Koala 側に Pixiu と同名のカテゴリを事前に作成してから再解析してください。</p><hr><p><strong>最終更新</strong>：2026 年 5 月</p>',52)])])}const b=t(r,[["render",e]]);export{g as __pageData,b as default};
